CREATE TABLE IF NOT EXISTS muse_user_handles (user_id TEXT PRIMARY KEY NOT NULL CHECK (length(trim(user_id)) > 0), user_name TEXT NOT NULL CHECK (length(trim(user_name)) > 0), handle_name TEXT NOT NULL CHECK (length(trim(handle_name)) > 0 AND length(handle_name) <= 40), handle_key TEXT NOT NULL UNIQUE CHECK (length(handle_key) > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
